// Decides which appointment gets a reminder right now. Pure logic: reads the sheets, writes nothing.
// Decide a qué cita le toca un recordatorio ahora. Solo lee las hojas, no escribe nada.
// Sent reminders live in Seguimientos (origen = P33, cita_id, ronda = the appointment start it was sent for).
// Los recordatorios enviados viven en Seguimientos (origen = P33, cita_id, ronda = el inicio de la cita al que apuntaba).

// ⚙️ CONFIG — DEMO_MODE: reminders 15/10/5 min before (live demo). false = 48 h / 24 h / 2 h (production).
// ⚙️ CONFIG — DEMO_MODE: recordatorios 15/10/5 min antes (demo en vivo). false = 48 h / 24 h / 2 h (producción).
const DEMO_MODE = true;
const STEPS = [                                   // minutes before the appointment / minutos antes de la cita
  { paso: '48h', min: DEMO_MODE ? 15 : 48 * 60 },
  { paso: '24h', min: DEMO_MODE ? 10 : 24 * 60 },
  { paso: '2h',  min: DEMO_MODE ? 5  : 2 * 60 }
];
const MIN_BEFORE = DEMO_MODE ? 1 : 30;             // too close to the appointment → no reminder / muy cerca → nada
const SEND_HOURS = [8, 20];                        // production only / solo producción (hora del spa)
const MAX_PER_RUN = 20;
const ACTIVE = ['agendada', 'confirmada', 'reprogramada'];

// --- Sheets → rows (same order as the batchGet URL) / Hojas → filas (mismo orden que la URL)
const SHEETS = ['Leads', 'Citas', 'Seguimientos', 'Negocio', 'Servicios'];
const ranges = $input.first().json.valueRanges || [];
const toRows = (vr) => {
  const v = (vr && vr.values) || [];
  const h = v[0] || [];
  return v.slice(1)
    .map((r, i) => { const o = { row_number: i + 2 }; h.forEach((k, j) => { o[k] = r[j] === undefined ? '' : String(r[j]); }); return o; })
    .filter(o => h.some(k => o[k] !== ''));
};
const t = {};
SHEETS.forEach((s, i) => { t[s] = toRows(ranges[i]); });
const negocio = {};
t.Negocio.forEach(r => { if (r.clave) negocio[r.clave] = r.valor; });

const tz = negocio.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const parse = s => {
  const str = String(s || '').trim();
  for (const f of ['yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm']) {
    const d = DateTime.fromFormat(str, f, { zone: tz });
    if (d.isValid) return d;
  }
  return null;
};
const fmt = d => (d ? d.toFormat('yyyy-MM-dd HH:mm:ss') : '');
const servicioEn = {};   // nombre_es → nombre_en (for English reminders / para recordatorios en inglés)
t.Servicios.forEach(r => { if (r.nombre_es) servicioEn[r.nombre_es] = r.nombre_en || r.nombre_es; });
const leads = {};
t.Leads.forEach(l => { leads[l.lead_id] = l; });

// Production: only between 8:00 and 20:00 (spa time). A reminder that falls outside goes out at 8:00.
// Producción: solo de 8:00 a 20:00 (hora del spa). Uno que cae fuera sale a las 8:00.
const inHours = DEMO_MODE || (now.hour >= SEND_HOURS[0] && now.hour < SEND_HOURS[1]);

const due = [];
const report = [];   // why each appointment was / was not picked / por qué se eligió o no cada cita
for (const cita of t.Citas) {
  const why = (motivo, extra = {}) => report.push({ cita_id: cita.cita_id, estado: cita.estado, motivo, ...extra });
  if (!ACTIVE.includes(cita.estado)) { why('estado_no_aplica'); continue; }

  const inicio = parse(cita.inicio);
  if (!inicio) { why('inicio_invalido'); continue; }
  const minsLeft = inicio.diff(now, 'minutes').minutes;
  if (minsLeft <= MIN_BEFORE) { why('muy_cerca_o_pasada', { inicio: cita.inicio }); continue; }

  const lead = leads[cita.lead_id];
  if (!lead) { why('lead_no_existe'); continue; }
  if (lead.estado === 'opt_out') { why('opt_out'); continue; }
  const whatsapp = cita.whatsapp || lead.whatsapp;
  if (!whatsapp) { why('sin_whatsapp'); continue; }

  // Confirmed → only the friendly "see you today" at 2 h. Not confirmed → ask at every step.
  // Confirmada → solo el "te esperamos" de las 2 h. Sin confirmar → se pide confirmar en cada paso.
  const steps = cita.estado === 'confirmada' ? STEPS.filter(s => s.paso === '2h') : STEPS;

  // The latest step whose time already came. Earlier steps that were missed are skipped (no bursts).
  // El último paso cuya hora ya llegó. Los anteriores que no salieron se saltan (nada de ráfagas).
  const ronda = cita.inicio;                                   // a rescheduled appointment starts a new round
  const anchor = parse(cita.ultima_actualizacion) || parse(cita.fecha_creacion);
  const fired = steps.filter(s => inicio.minus({ minutes: s.min }) <= now);
  if (!fired.length) {
    const next = steps[0];
    why('aun_no', { siguiente: next.paso, cuando: fmt(inicio.minus({ minutes: next.min })) });
    continue;
  }
  const step = fired[fired.length - 1];
  const fireAt = inicio.minus({ minutes: step.min });

  // Booked / rescheduled / confirmed after this step's time → she was just in touch, skip this step.
  // Agendó / reprogramó / confirmó después de la hora de este paso → acaba de hablar, se salta el paso.
  if (anchor && anchor > fireAt) { why('reciente', { paso: step.paso, cambio: fmt(anchor) }); continue; }

  const sent = t.Seguimientos.filter(s => s.origen === 'P33' && s.cita_id === cita.cita_id && s.ronda === ronda);
  const sentIdx = Math.max(-1, ...sent.map(s => STEPS.findIndex(x => x.paso === s.paso)));
  if (sentIdx >= STEPS.findIndex(x => x.paso === step.paso)) { why('ya_enviado', { paso: step.paso }); continue; }
  if (!inHours) { why('fuera_de_horario', { paso: step.paso }); continue; }

  const plantilla = cita.estado === 'confirmada' ? 'te_esperamos' : (step.paso === '2h' ? 'ultimo_aviso' : 'confirmar');
  due.push({
    cita_id: cita.cita_id, lead_id: cita.lead_id, nombre: cita.nombre || lead.nombre, whatsapp,
    idioma: lead.idioma || 'es', servicio: cita.servicio, servicio_en: servicioEn[cita.servicio] || cita.servicio, inicio: cita.inicio, fin: cita.fin,
    estado_cita: cita.estado, paso: step.paso, ronda, plantilla
  });
  why('toca', { paso: step.paso, plantilla });
}

const picked = due.slice(0, MAX_PER_RUN);
return picked.length
  ? picked.map(d => ({ json: { ...d, demo_mode: DEMO_MODE, ahora: fmt(now), negocio } }))
  : [{ json: { nada: true, ahora: fmt(now), demo_mode: DEMO_MODE, report } }];

// Fills the fixed reminder template (Meta "utility" style: fixed text + variables). No AI: $0 per message.
// Llena la plantilla fija del recordatorio (estilo "utility" de Meta: texto fijo + variables). Sin IA: $0 por mensaje.
// Templates / Plantillas: confirmar (48 h, 24 h) · ultimo_aviso (2 h, not confirmed) · te_esperamos (2 h, confirmed)
// "Consulta + …" → "consulta + …" mid-sentence (keeps acronyms like "HydraFacial" only if 2nd letter is upper)
const lower = s => (s && s[1] && s[1] === s[1].toLowerCase() ? s[0].toLowerCase() + s.slice(1) : s);
const T = {
  es: {
    confirmar: v => `Hola ${v.nombre} 👋 Soy ${v.asistente}, de ${v.spa}. Te recuerdo tu cita:\n\n🗓 ${v.dia}\n🕐 ${v.hora}\n💆 ${v.servicio}\n\n¿Nos confirmas? Responde *SÍ* para confirmar. Si necesitas cambiar la hora o cancelar, dímelo por aquí y lo hacemos en un momento.\n\nResponde STOP si no quieres recibir más mensajes.`,
    ultimo_aviso: v => `Hola ${v.nombre}, tu cita en ${v.spa} es ${v.dia} a las ${v.hora} (${v.servicio}). ¿Confirmas que vienes? Responde *SÍ* o dime si necesitas cambiarla.\n\n📍 ${v.direccion}`,
    te_esperamos: v => `Hola ${v.nombre} 💛 Te esperamos ${v.dia} a las ${v.hora} para tu ${lower(v.servicio)}.\n\n📍 ${v.direccion}${v.parqueadero ? '\n🚗 ' + v.parqueadero : ''}\n\nSi te surge algo, escríbeme por aquí.`
  },
  en: {
    confirmar: v => `Hi ${v.nombre} 👋 This is ${v.asistente} from ${v.spa}. A quick reminder of your appointment:\n\n🗓 ${v.dia}\n🕐 ${v.hora}\n💆 ${v.servicio}\n\nCan you confirm? Reply *YES* to confirm. If you need to change the time or cancel, just tell me here and I'll take care of it.\n\nReply STOP to opt out.`,
    ultimo_aviso: v => `Hi ${v.nombre}, your appointment at ${v.spa} is ${v.dia} at ${v.hora} (${v.servicio}). Are you still coming? Reply *YES* or tell me if you need to change it.\n\n📍 ${v.direccion}`,
    te_esperamos: v => `Hi ${v.nombre} 💛 We'll see you ${v.dia} at ${v.hora} for your ${lower(v.servicio)}.\n\n📍 ${v.direccion}${v.parqueadero ? '\n🚗 ' + v.parqueadero : ''}\n\nIf anything comes up, just message me here.`
  }
};

return $input.all().map(item => {
  const r = item.json;
  const n = r.negocio || {};
  const lang = String(r.idioma).toLowerCase().startsWith('en') ? 'en' : 'es';
  const tz = n.zona_horaria || 'America/Phoenix';
  const inicio = DateTime.fromFormat(String(r.inicio).slice(0, 16), 'yyyy-MM-dd HH:mm', { zone: tz }).setLocale(lang);
  const today = $now.setZone(tz).startOf('day');
  const days = Math.round(inicio.startOf('day').diff(today, 'days').days);

  // "today" / "tomorrow" / weekday + date — in the client's language / en el idioma de la clienta
  const fecha = lang === 'es' ? inicio.toFormat("cccc d 'de' LLLL") : inicio.toFormat('cccc, LLLL d');
  const dia = days === 0 ? (lang === 'es' ? 'hoy' : 'today')
            : days === 1 ? (lang === 'es' ? 'mañana, ' + fecha : 'tomorrow, ' + fecha)
            : fecha;
  const hora = lang === 'es'
    ? inicio.toFormat('h:mm') + (inicio.hour < 12 ? ' a. m.' : ' p. m.')
    : inicio.toFormat('h:mm a');

  const v = {
    nombre: String(r.nombre || '').trim().split(/\s+/)[0] || (lang === 'es' ? 'hola' : 'there'),
    asistente: n.nombre_asistente || 'Sofía', spa: n.nombre || 'Lumière Aesthetics',
    dia, hora, servicio: lang === 'en' ? (r.servicio_en || r.servicio) : r.servicio, direccion: n.direccion || '', parqueadero: n.parqueadero || ''
  };
  const mensaje = T[lang][r.plantilla](v);

  // Input for P31e - Lumière Send WhatsApp (+ the reminder data for the log) / Entrada para P31e (+ datos para el log)
  return { json: {
    lead_id: r.lead_id, whatsapp: r.whatsapp, mensaje, origen: 'P33', rol: 'assistant', off_topic: false, solo_registrar: false,
    cita_id: r.cita_id, paso: r.paso, ronda: r.ronda, plantilla: r.plantilla, idioma: lang
  } };
});

// One row for Seguimientos per reminder, sent or failed. / Una fila en Seguimientos por recordatorio, enviado o fallido.
// Columns / Columnas: seguimiento_id, fecha, lead_id, origen, secuencia, ronda, paso, canal, mensaje, message_id, resultado, cita_id
const reminders = $('Build Reminder').all();
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
return $input.all().map((item, i) => {
  const t = reminders[i].json;
  const r = item.json || {};
  const fecha = r.fecha || $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
  const resultado = (r.ok === false || r.estado_entrega === 'error') ? 'error: ' + (r.error || 'send_failed') : (r.estado_entrega || 'queued');
  return { json: {
    row: ['SEG-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, t.lead_id, 'P33', 'recordatorio_cita', t.ronda, t.paso,
          'whatsapp', t.mensaje, r.wa_message_sid || '', resultado, t.cita_id],
    cita_id: t.cita_id, paso: t.paso, plantilla: t.plantilla, resultado
  } };
});
